const only = [];
const byTicket = {"VIN-522":[968856331,968856332,968856333,968856334,968856335],"VIN-502":[968856336, 968856337, 968856338, 968856339, 968856340, 968856341, 968856342, 968856343, 968856344, 968856345, 968856346, 968856347, 968856348, 968856349, 968856350, 968856351, 968856352, 968856353, 968856354, 968856355, 968856356, 968856357, 968856358, 968856359, 968856360, 968856361, 968856362]};
const payload = [];
for (const t of Object.keys(byTicket)) { for (const id of byTicket[t]) { payload.push({ key_id: id, tag: t }); } }
const rows = only.length ? payload.filter(function (p) { return only.indexOf(p.key_id) >= 0; }) : payload;
