const P = $('Params').first().json; const b = $input.first().json.body || {}; const cur = {};
for (const k of (b.keys || [])) { cur[k.key_id] = k; }
const out = []; const skipped = []; let batch = [];
for (const r of P.rows) {
  const k = cur[r.key_id]; if (!k) { skipped.push({ id: r.key_id, why: 'not found' }); continue; }
  if (k.is_archived) { skipped.push({ id: r.key_id, why: 'archived' }); continue; }
  const o = { key_id: r.key_id }; let any = false;
  if ((k.tags || []).indexOf(r.tag) < 0) { o.tags = [r.tag]; o.merge_tags = true; any = true; }
  const d = k.description || '';
  if (d.indexOf(r.tag) < 0) { o.description = d ? (d.replace(/\s+$/, '') + ' (' + r.tag + ')') : r.tag; any = true; }
  if (r.es) {
    const t = (k.translations || []).filter(function (x) { return (x.language_iso || '').toLowerCase() === 'es'; })[0];
    if (t && String(t.translation || '').trim()) { skipped.push({ id: r.key_id, why: 'es not empty', by: t.modified_by_email }); }
    else { o.translations = [{ language_iso: 'es', translation: r.es, is_unverified: !!r.unverified }]; any = true; }
  }
  if (any) { batch.push(o); if (batch.length === 40) { out.push({ json: { project_id: P.project_id, body: { keys: batch } } }); batch = []; } }
}
if (batch.length) { out.push({ json: { project_id: P.project_id, body: { keys: batch } } }); }
if (out.length === 0) { out.push({ json: { project_id: P.project_id, body: null, skipped: skipped } }); }
out[0].json.skipped = skipped;
return out;

const P = $('Params').first().json; const want = {}; for (const r of P.rows) { want[r.key_id] = r; }
const res = $input.all(); const bad = []; let ok = 0; const status = [];
for (const it of res) {
  const r = it.json; status.push(r.statusCode);
  for (const k of ((r.body && r.body.keys) || [])) {
    const w = want[k.key_id]; if (!w) { continue; }
    const probs = [];
    if ((k.tags || []).indexOf(w.tag) < 0) { probs.push('tag'); }
    if (String(k.description || '').indexOf(w.tag) < 0) { probs.push('desc'); }
    if (w.es) { const t = (k.translations || []).filter(function (x) { return (x.language_iso || '').toLowerCase() === 'es'; })[0]; if (!t || !t.translation) { probs.push('es'); } }
    if (probs.length) { bad.push({ id: k.key_id, probs: probs, tags: k.tags }); } else { ok++; }
  }
  for (const e of ((r.body && r.body.errors) || [])) { bad.push({ error: e }); }
}
return [{ json: { http: status, updated_ok: ok, problems: bad, skipped: $('Build').first().json.skipped } }];
